import { RiskAssessmentChanges } from './risk-assessment-changes';
import { RiskAssessmentSnapshotExposure } from './risk-assessment-snapshot-exposure';
import { RiskAssessmentSnapshotPublicExploit } from './risk-assessment-snapshot-public-exploit';
import { RiskAssessmentSnapshotRiskLevel } from './risk-assessment-snapshot-risk-level';
import { RiskAssessmentSnapshotVulnerableFunctionUsage } from './risk-assessment-snapshot-vulnerable-function-usage';
/**
 * A snapshot of the risk assessment of a security problem.
 */
export interface RiskAssessmentSnapshot {
    /**
     * The risk score (1-10) from the CVSS score.
     */
    baseRiskScore?: number;
    changes?: RiskAssessmentChanges;
    exposure?: RiskAssessmentSnapshotExposure;
    /**
     * The number of currently affected entities.
     */
    numberOfAffectedEntities?: number;
    /**
     * The number of currently affected nodes.
     */
    numberOfAffectedNodes?: number;
    /**
     * The number of currently affected process groups.
     */
    numberOfAffectedProcessGroups?: number;
    /**
     * The number of data assets that are currently reachable by affected entities.
     */
    numberOfReachableDataAssets?: number;
    /**
     * The number of related attacks.
     */
    numberOfRelatedAttacks?: number;
    publicExploit?: RiskAssessmentSnapshotPublicExploit;
    riskLevel?: RiskAssessmentSnapshotRiskLevel;
    /**
     * The Davis risk score (1-10).
     *
     *  It is calculated by Dynatrace on the basis of CVSS score.
     */
    riskScore?: number;
    vulnerableFunctionUsage?: RiskAssessmentSnapshotVulnerableFunctionUsage;
}
